     9	import java.math.BigDecimal;
    10	
    11	public class CnpjFatura implements DocumentGenerator {
    12	    @Override
    13	    public Document generate(Reservation reservation, Room room) {
    14	        String checkInStr = DateUtils.formatDate(reservation.getCheckIn());
    15	        String checkOutStr = DateUtils.formatDate(reservation.getCheckOut());
    16	        String nightsStr = getNightsLabel(reservation.getNights());
    17	        String subtotalStr = formatMoney(reservation.getSubtotal());
    18	        String discountStr = reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0
    19	            ? formatMoney(reservation.getDiscount())
    20	            : null;
    21	        String totalStr = formatMoney(reservation.getTotal());
    22	
    23	        BigDecimal iss = MoneyRounder.round(reservation.getTotal().multiply(new BigDecimal("0.05")));
    24	        String issStr = formatMoney(iss);
    25	
    26	        StringBuilder sb = new StringBuilder();
    27	        sb.append("Fatura de hospedagem nº ").append(reservation.getId()).append("\n");
    28	        sb.append("Empresa: ").append(reservation.getCompanyName())
    29	            .append(" (CNPJ ").append(reservation.getCompanyCnpj()).append(")\n");
    30	        sb.append("Hóspede: ").append(reservation.getGuestName()).append("\n");
    31	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    32	            .append(" (").append(room.type()).append(")\n");
    33	        sb.append("Entrada: ").append(checkInStr)
    34	            .append(" | Saída: ").append(checkOutStr)
    35	            .append(" | ").append(nightsStr).append("\n");
    36	        sb.append("Diárias: ").append(subtotalStr).append("\n");
    37	        if (discountStr != null) {
    38	            sb.append("Desconto: ").append(discountStr).append("\n");
    39	        }
    40	        sb.append("Total: ").append(totalStr).append("\n");
    41	        sb.append("ISS retido (5%): ").append(issStr);
    42	
    43	        return new Document(
    44	            "Fatura de hospedagem",
    45	            reservation.getId(),
    46	            reservation.getGuestName(),
    47	            null,
    48	            reservation.getCompanyCnpj(),
    49	            reservation.getCompanyName(),
    50	            null,
    51	            null,
    52	            reservation.getRoomNumber(),
    53	            room.type().toString(),
    54	            checkInStr,
    55	            checkOutStr,
    56	            reservation.getNights(),
    57	            reservation.getSubtotal(),
    58	            reservation.getDiscount(),
    59	            reservation.getTotal(),
    60	            sb.toString()
    61	        );
    62	    }
    63	
    64	    private String getNightsLabel(int nights) {
    65	        return nights == 1 ? "1 diária" : nights + " diárias";
    66	    }
    67	
    68	    private String formatMoney(BigDecimal value) {
    69	        String formatted = String.format("%.2f", value);
    70	        return "R$ " + formatted.replace(".", ",");
    71	    }
    72	}
