     1	package com.pousadamareaalta.service;
     2	
     3	import com.pousadamareaalta.document.*;
     4	import com.pousadamareaalta.model.Document;
     5	import com.pousadamareaalta.model.Reservation;
     6	import com.pousadamareaalta.model.Room;
     7	
     8	public class DocumentService {
     9	    public Document generateDocument(Reservation reservation, Room room) {
    10	        DocumentGenerator generator = selectGenerator(reservation);
    11	        return generator.generate(reservation, room);
    12	    }
    13	
    14	    private DocumentGenerator selectGenerator(Reservation reservation) {
    15	        if (reservation.getGuestCpf() != null) {
    16	            return new CpfComprovante();
    17	        } else if (reservation.getCompanyCnpj() != null) {
    18	            return new CnpjFatura();
    19	        } else if (reservation.getGuestPassport() != null) {
    20	            return new PassportBookingReceipt();
    21	        }
    22	        throw new IllegalArgumentException("Unknown document type for reservation " + reservation.getId());
    23	    }
    24	}
