     3	import com.pousadamareaalta.api.ApiHandlers;
     4	import com.pousadamareaalta.service.*;
     5	import io.javalin.Javalin;
     6	
     7	public class App {
     8	    public static void main(String[] args) {
     9	        int port = getPort();
    10	
    11	        RoomRepository roomRepository = new RoomRepository();
    12	        ReservationRepository reservationRepository = new ReservationRepository();
    13	        MessageService messageService = new MessageService();
    14	        DocumentService documentService = new DocumentService();
    15	        ReservationService reservationService = new ReservationService(
    16	            reservationRepository,
    17	            roomRepository,
    18	            messageService,
    19	            documentService
    20	        );
    21	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
    22	        ApiHandlers handlers = new ApiHandlers(
    23	            reservationService,
    24	            roomRepository,
    25	            reservationRepository,
    26	            messageService,
    27	            reportService
    28	        );
    29	
    30	        Javalin app = Javalin.create()
    31	            .start(port);
    32	
    33	        app.get("/rooms", handlers::getRooms);
    34	        app.post("/reservations", handlers::createReservation);
    35	        app.get("/reservations/{id}", handlers::getReservation);
    36	        app.post("/reservations/{id}/confirmation", handlers::confirmReservation);
    37	        app.post("/reservations/{id}/cancellation", handlers::cancelReservation);
    38	        app.post("/reservations/{id}/check-in", handlers::checkin);
    39	        app.post("/reservations/{id}/check-out", handlers::checkout);
    40	        app.get("/reservations/{id}/document", handlers::getDocument);
    41	        app.get("/messages", handlers::getMessages);
    42	        app.get("/reports/occupancy", handlers::getOccupancyReport);
    43	        app.get("/reports/revenue", handlers::getRevenueReport);
    44	
    45	        System.out.println("Servidor rodando na porta " + port);
    46	    }
    47	
    48	    private static int getPort() {
    49	        String portEnv = System.getenv("PORT");
    50	        return portEnv != null ? Integer.parseInt(portEnv) : 7070;
    51	    }
    52	}

