   199	    private BigDecimal calculateSubtotal(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, int nights) {
   200	        BigDecimal total = BigDecimal.ZERO;
   201	        LocalDate current = checkIn;
   202	        while (current.isBefore(checkOut)) {
   203	            BigDecimal rate = nightlyRate;
   204	            if (DateUtils.isHighSeason(current)) {
   205	                rate = MoneyRounder.round(rate.multiply(new BigDecimal("1.20")));
   206	            }
   207	            total = total.add(rate);
   208	            current = current.plusDays(1);
   209	        }
   210	        return MoneyRounder.round(total);
   211	    }
