   213	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
   214	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
   215	            return MoneyRounder.round(subtotal.multiply(new BigDecimal("0.15")));
   216	        }
   217	        return BigDecimal.ZERO;
   218	    }
