    29	    public List<Reservation> findByRoomAndDateRange(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    30	        List<Reservation> result = new ArrayList<>();
    31	        for (Reservation r : reservations.values()) {
    32	            if (r.getRoomNumber() == roomNumber && datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut)) {
    33	                result.add(r);
    34	            }
    35	        }
    36	        return result;
    37	    }
