  1	package com.pousadamareaalta.service;
  2	
  3	import com.pousadamareaalta.model.*;
  4	import com.pousadamareaalta.util.DateUtils;
  5	import com.pousadamareaalta.util.MoneyRounder;
  6	
  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	
 10	public class ReservationService {
 11	    private final ReservationRepository reservationRepository;
 12	    private final RoomRepository roomRepository;
 13	    private final MessageService messageService;
 14	    private final DocumentService documentService;
 15	
 16	    public ReservationService(
 17	        ReservationRepository reservationRepository,
 18	        RoomRepository roomRepository,
 19	        MessageService messageService,
 20	        DocumentService documentService
 21	    ) {
 22	        this.reservationRepository = reservationRepository;
 23	        this.roomRepository = roomRepository;
 24	        this.messageService = messageService;
 25	        this.documentService = documentService;
 26	    }
 27	
 28	    public Reservation createReservation(
 29	        int roomNumber,
 30	        String guestName,
 31	        String guestEmail,
 32	        String guestCpf,
 33	        String companyCnpj,
 34	        String companyName,
 35	        String guestPassport,
 36	        String guestCountry,
 37	        LocalDate checkIn,
 38	        LocalDate checkOut,
 39	        int guests,
 40	        RatePlan ratePlan
 41	    ) throws ValidationException {
 42	        Room room = roomRepository.findById(roomNumber);
 43	        if (room == null) {
 44	            throw new ValidationException("ROOM_NOT_FOUND", "Quarto não encontrado");
 45	        }
 46	
 47	        if (guests < 1) {
 48	            throw new ValidationException("INVALID_REQUEST", "Número de hóspedes inválido");
 49	        }
 50	
 51	        if (guests > room.capacity()) {
 52	            throw new ValidationException("CAPACITY_EXCEEDED", "Quarto não comporta esse número de hóspedes");
 53	        }
 54	
 55	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
 56	            throw new ValidationException("INVALID_REQUEST", "Data de saída deve ser após data de entrada");
 57	        }
 58	
 59	        int identificationCount = countIdentifications(guestCpf, companyCnpj, guestPassport);
 60	        if (identificationCount != 1) {
 61	            throw new ValidationException("INVALID_REQUEST", "Deve informar exatamente um tipo de identificação");
 62	        }
 63	
 64	        if (companyCnpj != null && (companyName == null || companyName.isEmpty())) {
 65	            throw new ValidationException("INVALID_REQUEST", "Razão social é obrigatória com CNPJ");
 66	        }
 67	
 68	        if (guestPassport != null && (guestCountry == null || guestCountry.isEmpty())) {
 69	            throw new ValidationException("INVALID_REQUEST", "País é obrigatório com passaporte");
 70	        }
 71	
 72	        java.util.List<Reservation> conflicting = reservationRepository.findByRoomAndDateRange(
 73	            roomNumber, checkIn, checkOut
 74	        );
 75	        for (Reservation r : conflicting) {
 76	            if (r.getStatus() != ReservationStatus.CANCELLED) {
 77	                throw new ValidationException("ROOM_UNAVAILABLE", "Quarto indisponível nessas datas");
 78	            }
 79	        }
 80	
 81	        int nights = DateUtils.calculateNights(checkIn, checkOut);
 82	        BigDecimal subtotal = calculateSubtotal(room.nightlyRate(), checkIn, checkOut, nights);
 83	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
 84	        BigDecimal total = MoneyRounder.round(subtotal.subtract(discount));
 85	
 86	        long reservationId = reservationRepository.generateId();
 87	        Reservation reservation = new Reservation(
 88	            reservationId,
 89	            roomNumber,
 90	            guestName,
 91	            guestEmail,
 92	            guestCpf,
 93	            companyCnpj,
 94	            companyName,
 95	            guestPassport,
 96	            guestCountry,
 97	            checkIn,
 98	            checkOut,
 99	            guests,
100	            ratePlan,
101	            nights,
102	            subtotal,
103	            discount,
104	            total
105	        );
106	
107	        return reservationRepository.save(reservation);
108	    }
109	
110	    public Reservation confirmReservation(long reservationId) throws ValidationException {
111	        Reservation reservation = reservationRepository.findById(reservationId);
112	        if (reservation == null) {
113	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada");
114	        }
115	
116	        if (reservation.getStatus() != ReservationStatus.PENDING) {
117	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Apenas reservas pendentes podem ser confirmadas");
118	        }
119	
120	        reservation.setStatus(ReservationStatus.CONFIRMED);
121	        reservation.setAmountPaid(reservation.getTotal());
122	
123	        Room room = roomRepository.findById(reservation.getRoomNumber());
124	        Document document = documentService.generateDocument(reservation, room);
125	
126	        String emailBody = buildConfirmationEmail(reservation, document.text());
127	        messageService.send("EMAIL", reservation.getGuestEmail(), "Reserva confirmada - Pousada Maré Alta", emailBody);
128	
129	        return reservation;
130	    }
131	
132	    public Reservation checkin(long reservationId) throws ValidationException {
133	        Reservation reservation = reservationRepository.findById(reservationId);
134	        if (reservation == null) {
135	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada");
136	        }
137	
138	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
139	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Apenas reservas confirmadas podem fazer check-in");
140	        }
141	
142	        reservation.setStatus(ReservationStatus.CHECKED_IN);
143	        return reservation;
144	    }
145	
146	    public Document checkout(long reservationId) throws ValidationException {
147	        Reservation reservation = reservationRepository.findById(reservationId);
148	        if (reservation == null) {
149	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada");
150	        }
151	
152	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
153	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Apenas hóspedes com check-in podem fazer checkout");
154	        }
155	
156	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
157	        Room room = roomRepository.findById(reservation.getRoomNumber());
158	        return documentService.generateDocument(reservation, room);
159	    }
160	
161	    public Reservation cancelReservation(long reservationId) throws ValidationException {
162	        Reservation reservation = reservationRepository.findById(reservationId);
163	        if (reservation == null) {
164	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada");
165	        }
166	
167	        ReservationStatus status = reservation.getStatus();
168	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
169	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Apenas reservas pendentes ou confirmadas podem ser canceladas");
170	        }
171	
172	        reservation.setStatus(ReservationStatus.CANCELLED);
173	
174	        if (status == ReservationStatus.CONFIRMED) {
175	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
176	                reservation.setRefund(reservation.getTotal());
177	            } else {
178	                reservation.setRefund(BigDecimal.ZERO);
179	            }
180	        }
181	
182	        return reservation;
183	    }
184	
185	    public Document getDocument(long reservationId) throws ValidationException {
186	        Reservation reservation = reservationRepository.findById(reservationId);
187	        if (reservation == null) {
188	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada");
189	        }
190	
191	        if (reservation.getStatus() == ReservationStatus.PENDING) {
192	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Apenas reservas pagas podem gerar segunda via");
193	        }
194	
195	        Room room = roomRepository.findById(reservation.getRoomNumber());
196	        return documentService.generateDocument(reservation, room);
197	    }
198	
199	    private BigDecimal calculateSubtotal(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, int nights) {
200	        BigDecimal total = BigDecimal.ZERO;
201	        LocalDate current = checkIn;
202	        while (current.isBefore(checkOut)) {
203	            BigDecimal rate = nightlyRate;
204	            if (DateUtils.isHighSeason(current)) {
205	                rate = MoneyRounder.round(rate.multiply(new BigDecimal("1.20")));
206	            }
207	            total = total.add(rate);
208	            current = current.plusDays(1);
209	        }
210	        return MoneyRounder.round(total);
211	    }
212	
213	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
214	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
215	            return MoneyRounder.round(subtotal.multiply(new BigDecimal("0.15")));
216	        }
217	        return BigDecimal.ZERO;
218	    }
219	
220	    private String buildConfirmationEmail(Reservation reservation, String documentText) {
221	        return "Olá, " + reservation.getGuestName() + "!\n\n" +
222	               "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
223	               documentText + "\n\n" +
224	               "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
225	               "Até breve!";
226	    }
227	
228	    private int countIdentifications(String guestCpf, String companyCnpj, String guestPassport) {
229	        int count = 0;
230	        if (guestCpf != null && !guestCpf.isEmpty()) count++;
231	        if (companyCnpj != null && !companyCnpj.isEmpty()) count++;
232	        if (guestPassport != null && !guestPassport.isEmpty()) count++;
233	        return count;
234	    }
235	
236	    public static class ValidationException extends Exception {
237	        public final String errorCode;
238	
239	        public ValidationException(String errorCode, String message) {
240	            super(message);
241	            this.errorCode = errorCode;
242	        }
243	    }
244	}

