     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.YearMonth;
    10	import java.util.*;
    11	import java.util.stream.Collectors;
    12	
    13	public class ReportService {
    14	    private final ReservationRepository reservationRepository;
    15	    private final RoomRepository roomRepository;
    16	
    17	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    18	        this.reservationRepository = reservationRepository;
    19	        this.roomRepository = roomRepository;
    20	    }
    21	
    22	    public String generateOccupancyReport(LocalDate date) {
    23	        StringBuilder sb = new StringBuilder();
    24	        sb.append("room,type,reservation,check_in,check_out\n");
    25	
    26	        List<Reservation> occupiedReservations = reservationRepository.findAll().stream()
    27	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
    28	            .filter(r -> r.getStatus() != ReservationStatus.PENDING)
    29	            .filter(r -> isOccupiedOnDate(r, date))
    30	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
    31	            .collect(Collectors.toList());
    32	
    33	        for (Reservation r : occupiedReservations) {
    34	            String checkInStr = DateUtils.formatDateIso(r.getCheckIn());
    35	            String checkOutStr = DateUtils.formatDateIso(r.getCheckOut());
    36	            sb.append(r.getRoomNumber()).append(",")
    37	                .append(roomRepository.findById(r.getRoomNumber()).type()).append(",")
    38	                .append(r.getId()).append(",")
    39	                .append(checkInStr).append(",")
    40	                .append(checkOutStr).append("\n");
    41	        }
    42	
    43	        int occupied = occupiedReservations.size();
    44	        int total = (int) roomRepository.findAll().stream().count();
    45	        sb.append("total,").append(occupied).append("/").append(total);
    46	
    47	        return sb.toString();
    48	    }
    49	
    50	    public String generateRevenueReport(String month) throws ReservationService.ValidationException {
    51	        YearMonth yearMonth;
    52	        try {
    53	            yearMonth = DateUtils.parseYearMonth(month);
    54	        } catch (Exception e) {
    55	            throw new ReservationService.ValidationException("INVALID_REQUEST", "Formato de mês inválido");
    56	        }
    57	
    58	        StringBuilder sb = new StringBuilder();
    59	        sb.append("reservation,room,check_in,check_out,status,amount\n");
    60	
    61	        List<Reservation> relevantReservations = reservationRepository.findAll().stream()
    62	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(yearMonth))
    63	            .filter(r -> r.getStatus() != ReservationStatus.PENDING)
    64	            .filter(r -> r.getAmountPaid().compareTo(BigDecimal.ZERO) > 0 || r.getStatus() == ReservationStatus.CANCELLED)
    65	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    66	                .thenComparingLong(Reservation::getId))
    67	            .collect(Collectors.toList());
    68	
    69	        BigDecimal totalAmount = BigDecimal.ZERO;
    70	        for (Reservation r : relevantReservations) {
    71	            String checkInStr = DateUtils.formatDateIso(r.getCheckIn());
    72	            String checkOutStr = DateUtils.formatDateIso(r.getCheckOut());
    73	
    74	            BigDecimal amount = r.getAmountPaid().subtract(
    75	                r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO
    76	            );
    77	
    78	            sb.append(r.getId()).append(",")
    79	                .append(r.getRoomNumber()).append(",")
    80	                .append(checkInStr).append(",")
    81	                .append(checkOutStr).append(",")
    82	                .append(r.getStatus()).append(",")
    83	                .append(formatMoneyForCsv(amount)).append("\n");
    84	
    85	            totalAmount = totalAmount.add(amount);
    86	        }
    87	
    88	        sb.append("total,,,,").append(formatMoneyForCsv(totalAmount));
    89	
    90	        return sb.toString();
    91	    }
    92	
    93	    private boolean isOccupiedOnDate(Reservation r, LocalDate date) {
    94	        return !date.isBefore(r.getCheckIn()) && date.isBefore(r.getCheckOut());
    95	    }
    96	
    97	    private String formatMoneyForCsv(BigDecimal value) {
    98	        return String.format("%.2f", value);
    99	    }
   100	}
