     9	    }
    10	
    11	    public static boolean isHighSeason(LocalDate date) {
    12	        int month = date.getMonthValue();
    13	        int day = date.getDayOfMonth();
    14	
    15	        if (month == 7) return true;
    16	        if (month == 12) return true;
    17	        if (month >= 1 && month <= 2) return true;
    18	
    19	        return false;
    20	    }
    21	
    22	    public static String formatDate(LocalDate date) {
    23	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
    24	    }
    25	
    26	    public static String formatDateIso(LocalDate date) {
    27	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
    28	    }
    29	
    30	    public static String formatDateEnglish(LocalDate date) {
